use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn all_below_threshold(vec: Seq<i8>, threshold: i8) -> bool {
    forall|i: int| 0 <= i < vec.len() ==> vec[i] < threshold
}

fn check_below_threshold(l: Vec<i8>, t: i8) -> (result: bool)
    ensures
        result == all_below_threshold(l@, t),
{
    let mut i: usize = 0;
    let mut all_below = true;
    
    while i < l.len()
        invariant
            0 <= i <= l.len(),
            all_below == all_below_threshold(l@.subrange(0, i as int), t),
        decreases l.len() - i,
    {
        if l[i] >= t {
            all_below = false;
        }
        i = i + 1;
    }
    
    all_below
}

}
